func (fx *FeaturestoreServiceFeaturestoreTestSuiteConfig) testList(t *testing.T) {
	fx.maybeSkip(t)
	// Method should fail with InvalidArgument if provided parent is invalid.
	t.Run("invalid parent", func(t *testing.T) {
		fx.maybeSkip(t)
		_, err := fx.Service().ListFeaturestores(fx.Context(), &ListFeaturestoresRequest{
			Parent: "invalid resource name",
		})
		assert.Equal(t, codes.InvalidArgument, status.Code(err), err)
	})

	// Method should fail with InvalidArgument is provided page token is not valid.
	t.Run("invalid page token", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		_, err := fx.Service().ListFeaturestores(fx.Context(), &ListFeaturestoresRequest{
			Parent:    parent,
			PageToken: "invalid page token",
		})
		assert.Equal(t, codes.InvalidArgument, status.Code(err), err)
	})

	// Method should fail with InvalidArgument is provided page size is negative.
	t.Run("negative page size", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		_, err := fx.Service().ListFeaturestores(fx.Context(), &ListFeaturestoresRequest{
			Parent:   parent,
			PageSize: -10,
		})
		assert.Equal(t, codes.InvalidArgument, status.Code(err), err)
	})

	{
		const resourcesCount = 5
		parent := fx.nextParent(t, true)
		parentMsgs := make([]*Featurestore, resourcesCount)
		for i := 0; i < resourcesCount; i++ {
			parentMsgs[i] = fx.create(t, parent)
		}

		// If parent is provided the method must only return resources
		// under that parent.
		t.Run("isolation", func(t *testing.T) {
			fx.maybeSkip(t)
			response, err := fx.Service().ListFeaturestores(fx.Context(), &ListFeaturestoresRequest{
				Parent:   parent,
				PageSize: 999,
			})
			assert.NilError(t, err)
			assert.DeepEqual(
				t,
				fx.normalizeAll(parentMsgs),
				fx.normalizeAll(fx.listed(t, parent, parentMsgs, response.Featurestores)),
				cmpopts.SortSlices(func(a, b *Featurestore) bool {
					return a.Name < b.Name
				}),
				protocmp.Transform(),
			)
		})

		// If there are no more resources, next_page_token should not be set.
		t.Run("last page", func(t *testing.T) {
			fx.maybeSkip(t)
			response, err := fx.Service().ListFeaturestores(fx.Context(), &ListFeaturestoresRequest{
				Parent:   parent,
				PageSize: int32(resourcesCount + fx.Preexisting),
			})
			assert.NilError(t, err)
			assert.Equal(t, "", response.NextPageToken)
		})

		// If there are more resources, next_page_token should be set.
		t.Run("more pages", func(t *testing.T) {
			fx.maybeSkip(t)
			response, err := fx.Service().ListFeaturestores(fx.Context(), &ListFeaturestoresRequest{
				Parent:   parent,
				PageSize: resourcesCount - 1,
			})
			assert.NilError(t, err)
			assert.Check(t, response.NextPageToken != "")
		})

		// Listing resource one by one should eventually return all resources.
		t.Run("one by one", func(t *testing.T) {
			fx.maybeSkip(t)
			msgs := make([]*Featurestore, 0, resourcesCount)
			var nextPageToken string
			for {
				response, err := fx.Service().ListFeaturestores(fx.Context(), &ListFeaturestoresRequest{
					Parent:    parent,
					PageSize:  1,
					PageToken: nextPageToken,
				})
				assert.NilError(t, err)
				assert.Equal(t, 1, len(response.Featurestores))
				msgs = append(msgs, response.Featurestores...)
				nextPageToken = response.NextPageToken
				if nextPageToken == "" {
					break
				}
			}
			assert.DeepEqual(
				t,
				fx.normalizeAll(parentMsgs),
				fx.normalizeAll(fx.listed(t, parent, parentMsgs, msgs)),
				cmpopts.SortSlices(func(a, b *Featurestore) bool {
					return a.Name < b.Name
				}),
				protocmp.Transform(),
			)
		})

		// When listing resource with page size zero the service should use a default value.
		t.Run("page size zero", func(t *testing.T) {
			fx.maybeSkip(t)
			response, err := fx.Service().ListFeaturestores(fx.Context(), &ListFeaturestoresRequest{
				Parent:   parent,
				PageSize: 0,
			})
			assert.NilError(t, err)
			// Server should use a default page size and return at least some results
			assert.Check(t, len(response.Featurestores) > 0, "expected server to return at least 1 resource with page_size=0")
		})

	}
	{
		const resourcesCount = 5
		parent := fx.nextParent(t, true)
		parentMsgs := make([]*Featurestore, resourcesCount)
		for i := 0; i < resourcesCount; i++ {
			parentMsgs[i] = fx.create(t, parent)
		}

		// Method should not return deleted resources.
		t.Run("deleted", func(t *testing.T) {
			fx.maybeSkip(t)
			const deleteCount = 3
			for i := 0; i < deleteCount; i++ {
				_, err := fx.Service().DeleteFeaturestore(fx.Context(), &DeleteFeaturestoreRequest{
					Name: parentMsgs[i].Name,
				})
				assert.NilError(t, err)
			}
			response, err := fx.Service().ListFeaturestores(fx.Context(), &ListFeaturestoresRequest{
				Parent:   parent,
				PageSize: 9999,
			})
			assert.NilError(t, err)
			assert.DeepEqual(
				t,
				fx.normalizeAll(parentMsgs[deleteCount:]),
				fx.normalizeAll(fx.listed(t, parent, parentMsgs[deleteCount:], response.Featurestores)),
				cmpopts.SortSlices(func(a, b *Featurestore) bool {
					return a.Name < b.Name
				}),
				protocmp.Transform(),
			)
		})

	}
}

func (fx *FeaturestoreServiceFeaturestoreTestSuiteConfig) testDelete(t *testing.T) {
	fx.maybeSkip(t)
	// Method should fail with InvalidArgument if no name is provided.
	t.Run("missing name", func(t *testing.T) {
		fx.maybeSkip(t)
		_, err := fx.Service().DeleteFeaturestore(fx.Context(), &DeleteFeaturestoreRequest{
			Name: "",
		})
		assert.Equal(t, codes.InvalidArgument, status.Code(err), err)
	})

	// Method should fail with InvalidArgument if the provided name is not valid.
	t.Run("invalid name", func(t *testing.T) {
		fx.maybeSkip(t)
		_, err := fx.Service().DeleteFeaturestore(fx.Context(), &DeleteFeaturestoreRequest{
			Name: "invalid resource name",
		})
		assert.Equal(t, codes.InvalidArgument, status.Code(err), err)
	})

	// Resource should be deleted without errors if it exists.
	t.Run("exists", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		created := fx.create(t, parent)
		_, err := fx.Service().DeleteFeaturestore(fx.Context(), &DeleteFeaturestoreRequest{
			Name: created.Name,
		})
		assert.NilError(t, err)
	})

	// Method should fail with NotFound if the resource does not exist.
	t.Run("not found", func(t *testing.T) {
		fx.maybeSkip(t)
		parent := fx.nextParent(t, false)
		created := fx.create(t, parent)
		_, err := fx.Service().DeleteFeaturestore(fx.Context(), &DeleteFeaturestoreRequest{
			Name: fx.notFoundName(created.Name),
		})
		assert.Equal(t, codes.NotFound, status.Code(err), err)
	})

	// Method should fail with InvalidArgument if the provided name only contains wildcards ('-')
	t.Run("only wildcards", func(t *testing.T) {
		fx.maybeSkip(t)
		_, err := fx.Service().DeleteFeaturestore(fx.Context(), &DeleteFeaturestoreRequest{
			Name: "projects/-/locations/-/featurestores/-",
		})
		assert.Equal(t, codes.InvalidArgument, status.Code(err), err)
	})

}

func (fx *FeaturestoreServiceFeaturestoreTestSuiteConfig) nextParent(t *testing.T, pristine bool) string {
	if pristine {
		fx.currParent++
	}
	if fx.currParent >= len(fx.Parents) {
		t.Fatal("need at least", fx.currParent+1, "parents")
	}
	return fx.Parents[fx.currParent]
}

func (fx *FeaturestoreServiceFeaturestoreTestSuiteConfig) peekNextParent(t *testing.T) string {
	next := fx.currParent + 1
	if next >= len(fx.Parents) {
		t.Fatal("need at least", next+1, "parents")
	}
	return fx.Parents[next]
}

func (fx *FeaturestoreServiceFeaturestoreTestSuiteConfig) maybeSkip(t *testing.T) {
	for _, skip := range fx.Skip {
		if strings.Contains(t.Name(), skip) {
			t.Skip("skipped because of .Skip")
		}
	}
}

func (fx *FeaturestoreServiceFeaturestoreTestSuiteConfig) normalize(msg *Featurestore) *Featurestore {
	if fx.Normalize == nil || msg == nil {
		return msg
	}
	normalized := proto.Clone(msg).(*Featurestore)
	fx.Normalize(normalized)
	return normalized
}

func (fx *FeaturestoreServiceFeaturestoreTestSuiteConfig) normalizeAll(msgs []*Featurestore) []*Featurestore {
	if fx.Normalize == nil {
		return msgs
	}
	normalized := make([]*Featurestore, len(msgs))
	for i, msg := range msgs {
		normalized[i] = fx.normalize(msg)
	}
	return normalized
}

func (fx *FeaturestoreServiceFeaturestoreTestSuiteConfig) listed(t *testing.T, parent string, want, got []*Featurestore) []*Featurestore {
	t.Helper()
	assert.Equal(t, len(want)+fx.Preexisting, len(got), "listed resources, with Preexisting")
	names := make(map[string]bool, len(want))
	for _, msg := range want {
		names[msg.Name] = true
	}
	created := make([]*Featurestore, 0, len(want))
	for _, msg := range got {
		assert.Check(t, strings.HasPrefix(msg.Name, parent+"/"), "listed resource is not under the parent")
		if names[msg.Name] {
			created = append(created, msg)
		}
	}
	return created
}

func (fx *FeaturestoreServiceFeaturestoreTestSuiteConfig) create(t *testing.T, parent string) *Featurestore {
	t.Helper()
	t.Skip("Long running create method not supported")
	return nil
}

func (fx *FeaturestoreServiceFeaturestoreTestSuiteConfig) notFoundName(name string) string {
	// appending to the resource name ensures it is valid
	return name + "notfound"
}

func (fx *FeaturestoreServiceFeaturestoreTestSuiteConfig) field(msg *Featurestore, name protoreflect.Name) *Featurestore {
	msg = fx.normalize(msg)
	fd := msg.ProtoReflect().Descriptor().Fields().ByName(name)
	only := &Featurestore{}
	if msg.ProtoReflect().Has(fd) {
		only.ProtoReflect().Set(fd, msg.ProtoReflect().Get(fd))
	}
	return only
}

func (fx *FeaturestoreServiceFeaturestoreTestSuiteConfig) withoutField(msg *Featurestore, name protoreflect.Name) *Featurestore {
	cleared := proto.Clone(msg).(*Featurestore)
	cleared.ProtoReflect().Clear(cleared.ProtoReflect().Descriptor().Fields().ByName(name))
	return cleared
}
